import bpy,json
from pathlib import Path
from collections import Counter
rows={}
for cn in ['Boat_Workshop','Pier_Working','Harbor_Arrival_Landing','Coast_CraftWarehouse']:
    c=bpy.data.collections[cn]
    items=[]
    for o in c.objects:
        if o.type!='MESH':continue
        if len(items)<12 or any(k in o.name for k in ['LandingDeck','Walkboard_00','Strake','Hull']):
            items.append({'name':o.name,'verts':len(o.data.vertices),'polys':len(o.data.polygons),'dimensions':list(o.dimensions),
            'material':[m.name for m in o.data.materials],'modifiers':[(m.type,getattr(m,'width',None),getattr(m,'segments',None)) for m in o.modifiers],
            'smooth_faces':sum(p.use_smooth for p in o.data.polygons)})
    rows[cn]={'objects':len(c.objects),'samples':items}
mats={}
for m in bpy.data.materials:
    if m.name in ['BoatWood_Lit','PierWood_Lit'] or m.name.startswith('HarborCraft_Joinery_'):
        mats[m.name]=[{'type':n.type,'image':n.image.filepath if n.type=='TEX_IMAGE' and n.image else None,
        'value':n.inputs['Strength'].default_value if n.type=='NORMAL_MAP' else n.inputs['Roughness'].default_value if n.type=='BSDF_PRINCIPLED' else None} for n in m.node_tree.nodes]
print(json.dumps({'collections':rows,'materials':mats,'ns_keys':list(bpy.app.driver_namespace.get('harbor_craft',{}).keys())},ensure_ascii=False))
